<div class="page-head"><div><h1>Notifications</h1><p class="muted">Expiry warnings (<?= e(setting('expiry_warning_days', '10,3,1')) ?> days), expirations, locks, renewals, imports.</p></div><div class="page-actions"><form method="post"><?= csrf_field() ?><button class="btn btn-ghost btn-sm">Mark all read</button></form></div></div>
<ul class="notif-list"><?php foreach ($items as $n): ?><li class="card notif lvl-<?= e($n['level']) ?><?= $n['read_at'] ? '' : ' is-unread' ?>"><strong><?= e($n['title']) ?></strong><?php if ($n['body']): ?><p><?= e($n['body']) ?></p><?php endif ?><span class="small muted"><?= e(fmt_date($n['created_at'], true)) ?><?php if ($n['shop_id']): ?> · <a href="/superadmin/shops/<?= (int) $n['shop_id'] ?>/"><?= e($n['shop_name'] ?? 'shop') ?></a><?php endif ?> · <?= e($n['type']) ?></span></li><?php endforeach ?>
<?php if (!$items): ?><li class="muted">No notifications.</li><?php endif ?></ul><?= pager_html($pg, '/superadmin/notifications/') ?>
